const res = $input.first().json;
const raw = (res.content && res.content[0] && res.content[0].text) ? res.content[0].text : '';
let txt = raw.trim();
if (txt.startsWith('```')) { txt = txt.substring(txt.indexOf('\n') + 1); if (txt.endsWith('```')) txt = txt.slice(0, -3); txt = txt.trim(); }
let brainstorm;
try { brainstorm = JSON.parse(txt); } catch (e) { brainstorm = { parse_error: e.message, raw }; }
return [{ json: { topic: $('Set Topic').first().json.topic, brainstorm } }];

const input = $input.first().json;
let body = (input && input.body !== undefined) ? input.body : input;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
body = body || {};
const chosen_angle = (body.chosen_angle || body.angle || '').toString();
const angle_notes = (body.angle_notes || body.notes || '').toString();
const rawKeywords = body.keywords || '';
let keywords = [];
if (Array.isArray(rawKeywords)) { keywords = rawKeywords.map(s => String(s).trim()).filter(Boolean); }
else if (typeof rawKeywords === 'string' && rawKeywords.trim()) { keywords = rawKeywords.split(',').map(s => s.trim()).filter(Boolean); }
let target_word_count = Number(body.target_word_count);
if (!Number.isFinite(target_word_count) || target_word_count < 300 || target_word_count > 5000) { target_word_count = 1500; }
const job_id = $('Save Job').first().json.id;
const topic = $('Set Topic').first().json.topic;
return [{ json: { job_id, topic, chosen_angle, angle_notes, keywords, target_word_count } }];

