const res = $input.first().json;
const predictions = res.predictions || [];
const first = predictions[0] || {};
const image_b64 = first.bytesBase64Encoded || '';
const mime_type = first.mimeType || 'image/png';
if (!image_b64) { throw new Error('No image in Gemini response: ' + JSON.stringify(res).slice(0, 500)); }
const job_id = $('Parse Image Prompt').first().json.job_id;
const prompt = $('Parse Image Prompt').first().json.prompt;
return [{ json: { job_id, prompt, image_b64, mime_type } }];

const input = $input.first().json;
